    const fl_value kandidat = fl_t10662; /* пусть «кандидат» */
    fl_value fl_t10666 = fl_nothing(); /* «содержит» */
    FL_TRY(fl_b_soderzhit(ctx, vzyato, kandidat, &fl_t10666, error));
    bool fl_t10667 = false;
