      FL_TRY(fl_add(ctx, suffiks, fl_number(1.0), &fl_t10668, error));
      const fl_value fl_t10669 = zhelaemoe;
      const fl_value fl_t10670 = vzyato;
      zhelaemoe = fl_t10669;
      vzyato = fl_t10670;
      suffiks = fl_t10668;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Свободное имя", error));
